@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--ice:#9ce8ef;--gold:#ffcf80;--white:#edf6f5;--muted:#91a5aa}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071521;color:var(--white);font-family:Manrope,system-ui,sans-serif}#game-shell{position:relative;width:100%;height:100dvh;overflow:hidden;background:radial-gradient(ellipse at 52% 43%,#244e59 0,#102d3a 33%,#071521 78%)}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{position:absolute;inset:0;pointer-events:none;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:screen}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:86px;padding:0 clamp(20px,5.3vw,82px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d5faff1a;background:linear-gradient(180deg,#071521b5,transparent)}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:26px;color:var(--ice);text-shadow:0 0 20px #81f4ff}.brand b{display:block;font-size:12px;letter-spacing:.23em}.brand small{display:block;margin-top:3px;font:9px 'DM Mono',monospace;letter-spacing:.18em;color:#a6c1c5}.route{display:flex;gap:14px;align-items:center;font:10px 'DM Mono',monospace;letter-spacing:.14em;color:#bed3d4}.route i{width:53px;height:1px;background:linear-gradient(90deg,#9ce8ef77,#9ce8ef);position:relative}.route i:after{content:'';position:absolute;right:0;top:-3px;width:7px;height:7px;border-radius:50%;background:var(--ice);box-shadow:0 0 12px var(--ice)}.icon-btn{width:37px;height:37px;border:1px solid #d9fbff3d;background:#09202c80;border-radius:50%;color:var(--ice);font-size:16px;cursor:pointer}.mission-card{position:absolute;z-index:2;left:clamp(24px,9vw,138px);top:50%;transform:translateY(-42%);width:min(410px,calc(100vw - 48px));padding:0 0 0 24px;border-left:1px solid #a9eff27a;text-shadow:0 2px 20px #071521}.eyebrow,.objective-label,.alert-wrap,.pulse-meter,.hint,.bottom-note,.card-foot,.end-kicker{font:10px 'DM Mono',monospace;letter-spacing:.12em}.eyebrow{color:#c3d9d8;white-space:nowrap}.live-dot{display:inline-block;width:7px;height:7px;margin-right:8px;background:#a4f3d9;border-radius:50%;box-shadow:0 0 10px #a4f3d9}.divider{padding:0 9px;color:#76989d}.mission-card h1{font-size:clamp(42px,6.2vw,77px);line-height:.91;letter-spacing:-.07em;margin:19px 0 17px;font-weight:800}.mission-card h1 em{font-style:normal;color:var(--ice);letter-spacing:-.075em;text-shadow:0 0 32px #74e6ec38}.mission-card p{color:#c2d2d3;font-size:13px;line-height:1.75;margin:0 0 26px}.primary-btn{border:0;background:var(--ice);color:#08202a;padding:15px 19px;font:800 10px Manrope,sans-serif;letter-spacing:.13em;cursor:pointer;min-width:207px;box-shadow:0 0 25px #82eff42b;transition:transform .2s,box-shadow .2s}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 0 30px #82eff478}.primary-btn span{font-size:17px;margin-left:20px;vertical-align:-1px}.card-foot{margin-top:24px;color:#90aaad;font-size:8px;display:flex;gap:17px}.card-foot span+span{border-left:1px solid #91b1b475;padding-left:17px}.bottom-note{position:absolute;z-index:3;bottom:25px;left:clamp(20px,5.3vw,82px);right:clamp(20px,5.3vw,82px);display:flex;justify-content:space-between;color:#a2b9bc;font-size:9px;letter-spacing:.13em}.bottom-note i{color:var(--ice);font-style:normal}.hidden{display:none!important}.hud{position:absolute;z-index:3;top:106px;left:clamp(20px,5.3vw,82px);right:clamp(20px,5.3vw,82px);display:flex;align-items:flex-start;justify-content:space-between;gap:20px;text-shadow:0 2px 12px #000}.objective-label{font-size:9px;color:#a6c2c3;display:flex;gap:18px}.objective-label span{color:var(--gold)}.objective-main{margin-top:9px;font-size:15px;font-weight:700;display:flex;gap:9px;align-items:center}.target-icon{color:var(--gold);font-size:19px}.core-row{display:flex;gap:7px;margin:12px 0}.core-row i{width:21px;height:4px;background:#e2c47c;border-radius:4px;box-shadow:0 0 8px #f4d68b}.core-row i.empty{background:#527078;box-shadow:none}.alert-wrap{display:flex;flex-direction:column;gap:8px;align-items:center;color:#a6c2c3;font-size:9px}.alert-track{width:112px;height:4px;border-radius:3px;background:#29434b}.alert-track i{height:100%;width:4%;display:block;background:#9ce8ef;box-shadow:0 0 8px currentColor;transition:width .3s}.alert-wrap #alert-label{color:var(--ice)}.pulse-meter{display:flex;align-items:center;gap:10px;color:#c0d0ce;font-size:8px}.pulse-meter>div:nth-child(2) span{display:block;color:#a6c2c3;font-size:8px;margin-bottom:6px}.pulse-meter b{font-size:14px;color:var(--ice)}.pulse-meter b small{font-size:8px;color:#a6c2c3;font-weight:400}.pulse-icon{font-size:23px;color:var(--gold)}kbd{border:1px solid #c1e8e75c;padding:5px 7px;font:9px 'DM Mono',monospace;color:var(--ice);border-radius:3px}.hint{position:absolute;top:77px;right:0;color:var(--gold);font-size:9px}.end-card{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);width:min(410px,calc(100vw - 40px));padding:35px;background:#091d29e8;border:1px solid #a7f1f369;text-align:center;box-shadow:0 18px 90px #0009;backdrop-filter:blur(14px)}.end-kicker{color:var(--ice);font-size:9px}.end-card h2{font-size:32px;letter-spacing:-.05em;margin:13px 0}.end-card p{color:#aec2c3;font-size:13px;line-height:1.6;margin:0 0 23px}.toast{position:absolute;z-index:5;left:50%;top:24%;transform:translateX(-50%);padding:10px 16px;background:#091d29e6;border:1px solid #a7f1f36c;color:var(--ice);font:10px 'DM Mono',monospace;letter-spacing:.1em;white-space:nowrap}.controls{display:none}.shake{animation:shake .22s linear}@keyframes shake{25%{transform:translate(5px,-3px)}50%{transform:translate(-4px,2px)}75%{transform:translate(3px,1px)}}
@media(max-width:700px){.topbar{height:65px}.route{display:none}.mission-card{top:48%;left:25px;padding-left:17px;transform:translateY(-35%)}.mission-card h1{font-size:58px}.mission-card p{font-size:12px}.eyebrow{font-size:8px}.card-foot{font-size:7px;gap:9px}.card-foot span+span{padding-left:9px}.bottom-note{bottom:12px;font-size:7px}.hud{top:80px;left:17px;right:17px;gap:10px;flex-wrap:wrap}.objective{flex:1 1 54%}.alert-wrap{flex:0 0 auto}.pulse-meter{order:3;flex:0 0 auto}.hint{top:auto;bottom:-33px;left:0;right:auto;font-size:8px}.controls{display:flex;position:absolute;z-index:4;left:18px;right:18px;bottom:46px;justify-content:space-between;align-items:end;pointer-events:none}.dpad,.action-pad{pointer-events:auto}.dpad>button,.dpad div button,.action-pad button{width:43px;height:43px;border-radius:50%;border:1px solid #c1e8e75c;color:#e8ffff;background:#09202c99;font-size:17px;touch-action:none}.dpad>button{margin:0 auto 4px;display:block}.dpad div{display:flex;gap:4px}.action-pad{display:flex;gap:10px}.action-pad button{width:53px;height:53px;color:var(--ice);font-size:22px}.action-pad #touch-pulse{color:var(--gold)}.hud:not(.hidden)~.controls{display:flex}.mission-card:not(.hidden)~.controls{display:none}}@media(max-height:650px){.mission-card{top:53%;transform:translateY(-35%)}.mission-card h1{font-size:49px}.mission-card p{margin-bottom:14px}.card-foot{margin-top:12px}.bottom-note{bottom:9px}.hud{top:77px}.controls{bottom:34px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x102c38,.012);
const camera=new THREE.PerspectiveCamera(51,innerWidth/innerHeight,.1,240);
scene.add(new THREE.HemisphereLight(0xbde9ed,0x10202b,2.0));
const moon=new THREE.DirectionalLight(0xd9f4f4,3.2);moon.position.set(-5,12,8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
const cyanLight=new THREE.PointLight(0x4bdbe7,18,24);scene.add(cyanLight);
const goldLight=new THREE.PointLight(0xffbb5c,22,18);scene.add(goldLight);
const mat=(color,roughness=.7,metalness=.05,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:ei});
const mats={roof:mat(0x263e48,.55,.3),edge:mat(0x82989a,.4,.5),body:mat(0x183642,.45,.4),dark:mat(0x101f28,.65,.3),snow:mat(0xd1e4dc,.88),ice:mat(0x72d9e3,.25,.5,0x1ba8b5,.8),gold:mat(0xffcb70,.3,.3,0xf0922b,.9),red:mat(0xff665c,.3,.1,0xe52323,1.2),player:mat(0x253d48,.42,.3),coat:mat(0xd08b4c,.55,.1),visor:mat(0x73edf1,.22,.5,0x30b9c9,.8),rail:mat(0x92b5b4,.4,.65),rock:mat(0x203944,.95)};
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
const world=new THREE.Group();scene.add(world);
// Long rooftop and illuminated train sides; repeating couplers give the roof a readable railcar rhythm.
for(let i=0;i<8;i++){const z=18-i*17;box(world,0,-.35,z,8,.6,17,mats.body);box(world,0,-.01,z,7.45,.18,16.3,mats.roof);for(const x of [-3.88,3.88]){box(world,x,-.32,z, .22,.48,16.8,mats.edge);box(world,x,-.65,z, .07,.11,15,mats.gold,false)}for(const x of [-2.7,2.7])box(world,x,.12,z,.13,.14,15.8,mats.edge);for(let z2=z-7;z2<z+8;z2+=5){box(world,0,.1,z2,.33,.15,.25,mats.edge);}}
// Rooftop details and snow-swept wilderness.
const rand=(a,b)=>a+Math.random()*(b-a);
for(let i=0;i<78;i++){const side=Math.random()<.5?-1:1,z=rand(-128,36),x=side*rand(6,24),h=rand(2,12);const mountain=new THREE.Mesh(new THREE.ConeGeometry(rand(2,8),h,5),mats.rock);mountain.position.set(x,h/2-2,z);mountain.rotation.y=rand(0,6);scene.add(mountain);const cap=new THREE.Mesh(new THREE.ConeGeometry(rand(1.4,5),h*.33,5),mats.snow);cap.position.set(x,h*.75-2,z);cap.rotation.y=mountain.rotation.y;scene.add(cap)}
for(let side of [-1,1]){for(let x of [side*4.4,side*5.2]){const rail=box(world,x,-.72,-43,.08,.08,125,mats.rail,false);rail.castShadow=false;}}
// Glowing aurora curtains, stars and floating snow.
for(let i=0;i<100;i++){const s=sphere(scene,rand(-45,45),rand(7,28),rand(-130,20),rand(.025,.075),i%8===0?mats.ice:mats.snow);s.material= i%8===0?mats.ice: new THREE.MeshBasicMaterial({color:0xc9f0e9});}
const auroraMat=new THREE.MeshBasicMaterial({color:0x42c8b3,transparent:true,opacity:.08,side:THREE.DoubleSide,depthWrite:false});
for(let i=0;i<5;i++){const ribbon=new THREE.Mesh(new THREE.PlaneGeometry(45,10,20,1),auroraMat);ribbon.position.set(-10+i*7,16,-55-i*8);ribbon.rotation.y=.18+i*.06;ribbon.rotation.z=.12;scene.add(ribbon)}
const snowflakes=[];const snowMat=new THREE.MeshBasicMaterial({color:0xc8f1f1,transparent:true,opacity:.62});
for(let i=0;i<95;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(rand(.018,.045),5,5),snowMat);m.position.set(rand(-12,12),rand(1,16),rand(-100,15));scene.add(m);snowflakes.push(m)}
// Player model: insulated runner, glowing visor and pack.
const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);
const torso=box(avatar,0,.72,0,.5,.68,.34,mats.coat);box(avatar,0,1.25,0,.44,.42,.4,mats.player);box(avatar,0,1.3,-.215,.31,.16,.025,mats.visor,false);box(avatar,0,.75,.22,.37,.38,.12,mats.dark);
const limbs=[];for(const x of [-.22,.22]){const arm=box(avatar,x,.76,0,.16,.45,.17,mats.coat);limbs.push(arm);const leg=new THREE.Group();leg.position.set(x*.68,.42,0);avatar.add(leg);box(leg,0,-.2,0,.18,.43,.2,mats.player);box(leg,0,-.42,-.07,.2,.11,.34,mats.dark);limbs.push(leg)}
player.position.set(0,.2,0);
// Obstacles, collectible cipher cores, and polarity mag-lock gates.
const obstacles=[],cores=[],gates=[];
function obstacle(z,x,type){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);if(type==='crate'){box(g,0,.65,0,1.2,1.25,1.1,mats.dark);box(g,0,1.3,0,1.22,.1,1.12,mats.gold)}else if(type==='vent'){box(g,0,.5,0,1.5,.9,1.1,mats.edge);for(let i=-2;i<=2;i++)box(g,i*.22,.98,0,.09,.08,.8,mats.dark)}else{box(g,0,.42,0,1.25,.84,1.4,mats.red);box(g,0,1.1,0,.16,.42,.16,mats.gold);const light=sphere(g,0,1.37,0,.17,mats.red);light.material=mat(0xff433b,.25,.1,0xff1307,3)}obstacles.push({g,z,x,type,hit:false})}
function core(z,x){const g=new THREE.Group();g.position.set(x,1.15,z);world.add(g);const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.48),mats.gold);crystal.castShadow=true;g.add(crystal);const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.035,6,24),mats.gold);ring.rotation.x=Math.PI/2;g.add(ring);cores.push({g,z,x,taken:false})}
function gate(z){const g=new THREE.Group();g.position.set(0,0,z);world.add(g);for(const x of [-3.6,3.6]){box(g,x,1.35,0,.22,2.7,.32,mats.dark);const orb=sphere(g,x,2.85,0,.22,mats.ice);orb.userData.blink=true}box(g,0,2.7,0,7.35,.17,.3,mats.dark);for(let i=-3;i<=3;i++)box(g,i*.48,1.48,0,.15,2.05,.15,mats.red,false);const cage=new THREE.Mesh(new THREE.BoxGeometry(7.5,2.2,.12),new THREE.MeshBasicMaterial({color:0xe75a50,transparent:true,opacity:.13,side:THREE.DoubleSide}));cage.position.y=1.45;g.add(cage);gates.push({g,z,open:false});}
// Deliberate route: lane changes, a vault, cores, and two pulse-only gates.
obstacle(-13,-2.5,'vent');core(-20,2.45);obstacle(-27,0,'crate');obstacle(-34,2.5,'beacon');gate(-42);core(-50,-2.5);obstacle(-57,2.5,'vent');obstacle(-64,-2.5,'crate');gate(-73);core(-81,0);obstacle(-88,-2.5,'beacon');obstacle(-96,2.5,'crate');
// Engine cab at the end of the run.
const engine=new THREE.Group();engine.position.set(0,0,-108);world.add(engine);box(engine,0,.65,0,7.4,1.35,10,mats.body);box(engine,0,1.38,0,7.2,.22,9.7,mats.roof);box(engine,0,1.4,-3.3,5.4,.15,2.7,mats.edge);for(const x of [-1.6,0,1.6]){const w=box(engine,x,1.52,-3.4,.85,.07,1.4,mats.visor,false);w.material=mat(0x73edf1,.2,.5,0x55dce8,1.4)}box(engine,0,2.3,-4.7,4.2,1.9,1.1,mats.body);for(const x of [-1.45,1.45])sphere(engine,x,2.2,-5.27,.28,mats.gold);

// Interface and game rules.
const $=s=>document.querySelector(s),mission=$('#mission-card'),hud=$('#hud'),endCard=$('#end-card'),toast=$('#toast');
let running=false,ended=false,progress=0,playerX=0,jumpY=0,jumpV=0,pulseCharges=2,alert=0,coresTaken=0,toastTimer=0,elapsed=0,soundOn=false;
const keys={};
function showToast(text){toast.textContent=text;toast.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.add('hidden'),1500)}
function setAlert(v){alert=Math.max(0,Math.min(100,v));const fill=$('#alert-fill');fill.style.width=alert+'%';fill.style.background=alert>66?'#ff665c':alert>35?'#ffcf80':'#9ce8ef';$('#alert-label').textContent=alert>66?'HUNTED':alert>35?'WATCHFUL':'CLEAR';$('#alert-label').style.color=alert>66?'#ff665c':alert>35?'#ffcf80':'#9ce8ef'}
function updateCores(){[...$('#cores').children].forEach((el,i)=>el.classList.toggle('empty',i>=coresTaken));$('#objective-text').textContent=coresTaken===3?'Reach the engine cab':'Recover cipher cores'}
function begin(){running=true;ended=false;mission.classList.add('hidden');endCard.classList.add('hidden');hud.classList.remove('hidden');$('#touch-controls').classList.remove('hidden');progress=0;playerX=0;jumpY=0;pulseCharges=2;coresTaken=0;setAlert(0);updateCores();$('#pulse-count').innerHTML='02 <small>CHARGES</small>';obstacles.forEach(o=>o.hit=false);cores.forEach(c=>c.taken=false);gates.forEach(g=>{g.open=false;g.g.visible=true;g.g.scale.setScalar(1)});}
function finish(win){if(ended)return;ended=true;running=false;endCard.classList.remove('hidden');$('#end-kicker').textContent=win?'MISSION COMPLETE':'OPERATION BUSTED';$('#end-title').textContent=win?'Clean getaway.':'Caught in the snow.';$('#end-copy').textContent=win?`All ${coresTaken} cipher cores secured. The border is behind you.`:'Security locked the roof. Reset and try another route.'}
$('#start').addEventListener('click',begin);$('#restart').addEventListener('click',begin);
function pulse(){if(!running)return;if(pulseCharges<=0){showToast('NO CHARGES · FIND A CORE');return}pulseCharges--;$('#pulse-count').innerHTML=`0${pulseCharges} <small>CHARGES</small>`;let gateTarget=null;for(const g of gates){if(!g.open&&Math.abs((g.z+progress)-3.5)<9){gateTarget=g;break}}if(gateTarget){gateTarget.open=true;gateTarget.g.visible=false;setAlert(Math.max(0,alert-12));showToast('MAG-LOCK DISABLED · MOVE!');scene.fog.color.setHex(0x13444a);setTimeout(()=>scene.fog.color.setHex(0x102c38),550)}else{setAlert(Math.max(0,alert-5));showToast('POLARITY PULSE · SECURITY DISRUPTED')}const shell=$('#game-shell');shell.classList.remove('shake');void shell.offsetWidth;shell.classList.add('shake')}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e'&&!e.repeat)pulse();if((k===' '||k==='arrowup')&&!e.repeat&&running&&jumpY<=.01)jumpV=5.5;if(k==='enter'&&!running&&!ended)begin()});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function bindHold(button,key){button.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;button.setPointerCapture(e.pointerId)});for(const n of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(n,()=>keys[key]=false)}
document.querySelectorAll('[data-key]').forEach(b=>bindHold(b,b.dataset.key));$('#touch-pulse').addEventListener('pointerdown',e=>{e.preventDefault();pulse()});$('#touch-jump').addEventListener('pointerdown',e=>{e.preventDefault();if(running&&jumpY<=.01)jumpV=5.5});
$('#sound').addEventListener('click',()=>{soundOn=!soundOn;$('#sound').style.color=soundOn?'#ffcf80':'#9ce8ef';showToast(soundOn?'AUDIO ENABLED':'AUDIO MUTED')});
const clock=new THREE.Clock();
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.045);elapsed+=dt;
 if(running){const move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);playerX=THREE.MathUtils.clamp(playerX+move*dt*5,-2.55,2.55);if(keys.w||keys.arrowup)progress+=dt*8.3;else if(keys.s||keys.arrowdown)progress-=dt*4.5;else progress+=dt*5.15;progress=THREE.MathUtils.clamp(progress,0,110);jumpV-=dt*13;jumpY=Math.max(0,jumpY+jumpV*dt);if(jumpY===0)jumpV=0;
  player.position.x=THREE.MathUtils.damp(player.position.x,playerX,10,dt);player.position.y=.2+jumpY;avatar.rotation.z=THREE.MathUtils.damp(avatar.rotation.z,-move*.13,8,dt);avatar.position.y=Math.sin(elapsed*13)*.025;limbs[0].rotation.z=Math.sin(elapsed*9)*.12;limbs[1].rotation.x=Math.sin(elapsed*9)*.4;limbs[2].rotation.x=-Math.sin(elapsed*9)*.4;
  const worldZ=-progress;camera.position.set(player.position.x*.34,5.9,10.8);camera.lookAt(player.position.x*.12,1.1,-8.6);world.position.z=0; // the train remains still while the runner advances along its roof
  player.position.z=worldZ;
  const dist=Math.max(0,108-progress);$('#distance').textContent=`${Math.round(dist)} M`;
