import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x102c38,.012);
const camera=new THREE.PerspectiveCamera(51,innerWidth/innerHeight,.1,240);camera.position.set(0,5.9,10.8);camera.lookAt(0,1,-8.6);
scene.add(new THREE.HemisphereLight(0xbde9ed,0x10202b,2));const moon=new THREE.DirectionalLight(0xd9f4f4,3.2);moon.position.set(-5,12,8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
const cyanLight=new THREE.PointLight(0x4bdbe7,18,24);scene.add(cyanLight);const goldLight=new THREE.PointLight(0xffbb5c,22,18);scene.add(goldLight);
const mat=(color,roughness=.7,metalness=.05,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:ei});
const mats={roof:mat(0x263e48,.55,.3),edge:mat(0x82989a,.4,.5),body:mat(0x183642,.45,.4),dark:mat(0x101f28,.65,.3),snow:mat(0xd1e4dc,.88),ice:mat(0x72d9e3,.25,.5,0x1ba8b5,.8),gold:mat(0xffcb70,.3,.3,0xf0922b,.9),red:mat(0xff665c,.3,.1,0xe52323,1.2),player:mat(0x253d48,.42,.3),coat:mat(0xd08b4c,.55,.1),visor:mat(0x73edf1,.22,.5,0x30b9c9,.8),rail:mat(0x92b5b4,.4,.65),rock:mat(0x203944,.95)};
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,r,material){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
const world=new THREE.Group();scene.add(world);
for(let i=0;i<8;i++){const z=18-i*17;box(world,0,-.35,z,8,.6,17,mats.body);box(world,0,-.01,z,7.45,.18,16.3,mats.roof);for(const x of [-3.88,3.88]){box(world,x,-.32,z,.22,.48,16.8,mats.edge);box(world,x,-.65,z,.07,.11,15,mats.gold,false)}for(const x of [-2.7,2.7])box(world,x,.12,z,.13,.14,15.8,mats.edge);for(let z2=z-7;z2<z+8;z2+=5)box(world,0,.1,z2,.33,.15,.25,mats.edge)}
const rand=(a,b)=>a+Math.random()*(b-a);
for(let i=0;i<70;i++){const side=Math.random()<.5?-1:1,z=rand(-128,36),x=side*rand(6,24),h=rand(2,12),rot=rand(0,6);const mountain=new THREE.Mesh(new THREE.ConeGeometry(rand(2,8),h,5),mats.rock);mountain.position.set(x,h/2-2,z);mountain.rotation.y=rot;scene.add(mountain);const cap=new THREE.Mesh(new THREE.ConeGeometry(rand(1.4,5),h*.33,5),mats.snow);cap.position.set(x,h*.75-2,z);cap.rotation.y=rot;scene.add(cap)}
for(const side of [-1,1])for(const x of [side*4.4,side*5.2])box(world,x,-.72,-43,.08,.08,125,mats.rail,false);
for(let i=0;i<90;i++){const s=sphere(scene,rand(-45,45),rand(7,28),rand(-130,20),rand(.025,.075),mats.ice);s.material=new THREE.MeshBasicMaterial({color:i%8===0?0x9ce8ef:0xc9f0e9})}
const auroraMat=new THREE.MeshBasicMaterial({color:0x42c8b3,transparent:true,opacity:.08,side:THREE.DoubleSide,depthWrite:false});for(let i=0;i<5;i++){const ribbon=new THREE.Mesh(new THREE.PlaneGeometry(45,10,20,1),auroraMat);ribbon.position.set(-10+i*7,16,-55-i*8);ribbon.rotation.y=.18+i*.06;ribbon.rotation.z=.12;scene.add(ribbon)}
const snowflakes=[],snowMat=new THREE.MeshBasicMaterial({color:0xc8f1f1,transparent:true,opacity:.62});for(let i=0;i<95;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(rand(.018,.045),5,5),snowMat);m.position.set(rand(-12,12),rand(1,16),rand(-100,15));scene.add(m);snowflakes.push(m)}
const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);box(avatar,0,.72,0,.5,.68,.34,mats.coat);box(avatar,0,1.25,0,.44,.42,.4,mats.player);box(avatar,0,1.3,-.215,.31,.16,.025,mats.visor,false);box(avatar,0,.75,.22,.37,.38,.12,mats.dark);const limbs=[];for(const x of [-.22,.22]){limbs.push(box(avatar,x,.76,0,.16,.45,.17,mats.coat));const leg=new THREE.Group();leg.position.set(x*.68,.42,0);avatar.add(leg);box(leg,0,-.2,0,.18,.43,.2,mats.player);box(leg,0,-.42,-.07,.2,.11,.34,mats.dark);limbs.push(leg)}player.position.set(0,.2,0);
const obstacles=[],cores=[],gates=[];
function obstacle(z,x,type){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);if(type==='crate'){box(g,0,.65,0,1.2,1.25,1.1,mats.dark);box(g,0,1.3,0,1.22,.1,1.12,mats.gold)}else if(type==='vent'){box(g,0,.5,0,1.5,.9,1.1,mats.edge);for(let i=-2;i<=2;i++)box(g,i*.22,.98,0,.09,.08,.8,mats.dark)}else{box(g,0,.42,0,1.25,.84,1.4,mats.red);box(g,0,1.1,0,.16,.42,.16,mats.gold);sphere(g,0,1.37,0,.17,mats.red)}obstacles.push({g,z,x,type,hit:false})}
function core(z,x){const g=new THREE.Group();g.position.set(x,1.15,z);world.add(g);g.add(new THREE.Mesh(new THREE.OctahedronGeometry(.48),mats.gold));const ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.035,6,24),mats.gold);ring.rotation.x=Math.PI/2;g.add(ring);cores.push({g,z,x,taken:false})}
function gate(z){const g=new THREE.Group();g.position.set(0,0,z);world.add(g);for(const x of [-3.6,3.6]){box(g,x,1.35,0,.22,2.7,.32,mats.dark);sphere(g,x,2.85,0,.22,mats.ice)}box(g,0,2.7,0,7.35,.17,.3,mats.dark);for(let i=-3;i<=3;i++)box(g,i*.48,1.48,0,.15,2.05,.15,mats.red,false);const cage=new THREE.Mesh(new THREE.BoxGeometry(7.5,2.2,.12),new THREE.MeshBasicMaterial({color:0xe75a50,transparent:true,opacity:.13,side:THREE.DoubleSide}));cage.position.y=1.45;g.add(cage);gates.push({g,z,open:false})}
obstacle(-13,-2.5,'vent');core(-20,2.45);obstacle(-27,0,'crate');obstacle(-34,2.5,'beacon');gate(-42);core(-50,-2.5);obstacle(-57,2.5,'vent');obstacle(-64,-2.5,'crate');gate(-73);core(-81,0);obstacle(-88,-2.5,'beacon');obstacle(-96,2.5,'crate');
const engine=new THREE.Group();engine.position.set(0,0,-108);world.add(engine);box(engine,0,.65,0,7.4,1.35,10,mats.body);box(engine,0,1.38,0,7.2,.22,9.7,mats.roof);box(engine,0,1.4,-3.3,5.4,.15,2.7,mats.edge);for(const x of [-1.6,0,1.6])box(engine,x,1.52,-3.4,.85,.07,1.4,mats.visor,false);box(engine,0,2.3,-4.7,4.2,1.9,1.1,mats.body);for(const x of [-1.45,1.45])sphere(engine,x,2.2,-5.27,.28,mats.gold);

const $=s=>document.querySelector(s),mission=$('#mission-card'),hud=$('#hud'),endCard=$('#end-card'),toast=$('#toast');let running=false,ended=false,progress=0,playerX=0,jumpY=0,jumpV=0,pulseCharges=2,alert=0,coresTaken=0,toastTimer=0,elapsed=0,soundOn=false;const keys={};
function showToast(text){toast.textContent=text;toast.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.add('hidden'),1500)}
function setAlert(v){alert=Math.max(0,Math.min(100,v));$('#alert-fill').style.width=alert+'%';$('#alert-fill').style.background=alert>66?'#ff665c':alert>35?'#ffcf80':'#9ce8ef';$('#alert-label').textContent=alert>66?'HUNTED':alert>35?'WATCHFUL':'CLEAR';$('#alert-label').style.color=alert>66?'#ff665c':alert>35?'#ffcf80':'#9ce8ef'}
function updateCores(){[...$('#cores').children].forEach((el,i)=>el.classList.toggle('empty',i>=coresTaken));$('#objective-text').textContent=coresTaken===3?'Reach the engine cab':'Recover cipher cores'}
function begin(){running=true;ended=false;mission.classList.add('hidden');endCard.classList.add('hidden');hud.classList.remove('hidden');$('#touch-controls').classList.remove('hidden');progress=0;playerX=0;jumpY=0;jumpV=0;pulseCharges=2;coresTaken=0;setAlert(0);updateCores();$('#pulse-count').innerHTML='02 <small>CHARGES</small>';obstacles.forEach(o=>{o.hit=false;o.g.visible=true});cores.forEach(c=>{c.taken=false;c.g.visible=true});gates.forEach(g=>{g.open=false;g.g.visible=true});}
function finish(win){if(ended)return;ended=true;running=false;endCard.classList.remove('hidden');$('#end-kicker').textContent=win?'MISSION COMPLETE':'OPERATION BUSTED';$('#end-title').textContent=win?'Clean getaway.':'Caught in the snow.';$('#end-copy').textContent=win?`All ${coresTaken} cipher cores secured. The border is behind you.`:'Security locked the roof. Reset and try another route.'}
$('#start').addEventListener('click',begin);$('#restart').addEventListener('click',begin);
function pulse(){if(!running)return;if(pulseCharges<=0){showToast('NO CHARGES · FIND A CORE');return}pulseCharges--;$('#pulse-count').innerHTML=`0${pulseCharges} <small>CHARGES</small>`;let target=null;for(const g of gates)if(!g.open&&Math.abs((g.z+progress)-3.5)<9){target=g;break}if(target){target.open=true;target.g.visible=false;setAlert(Math.max(0,alert-12));showToast('MAG-LOCK DISABLED · MOVE!');scene.fog.color.setHex(0x13444a);setTimeout(()=>scene.fog.color.setHex(0x102c38),550)}else{setAlert(Math.max(0,alert-5));showToast('POLARITY PULSE · SECURITY DISRUPTED')}const shell=$('#game-shell');shell.classList.remove('shake');void shell.offsetWidth;shell.classList.add('shake')}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e'&&!e.repeat)pulse();if((k===' '||k==='arrowup')&&!e.repeat&&running&&jumpY<=.01)jumpV=5.5;if(k==='enter'&&!running&&!ended)begin()});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
function bindHold(button,key){button.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;button.setPointerCapture(e.pointerId)});for(const n of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(n,()=>keys[key]=false)}document.querySelectorAll('[data-key]').forEach(b=>bindHold(b,b.dataset.key));$('#touch-pulse').addEventListener('pointerdown',e=>{e.preventDefault();pulse()});$('#touch-jump').addEventListener('pointerdown',e=>{e.preventDefault();if(running&&jumpY<=.01)jumpV=5.5});$('#sound').addEventListener('click',()=>{soundOn=!soundOn;$('#sound').style.color=soundOn?'#ffcf80':'#9ce8ef';showToast(soundOn?'AUDIO ENABLED':'AUDIO MUTED')});
const clock=new THREE.Clock();function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()}addEventListener('resize',resize);
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.045);elapsed+=dt;
 if(running){const move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);playerX=THREE.MathUtils.clamp(playerX+move*dt*5,-2.55,2.55);if(keys.w||keys.arrowup)progress+=dt*8.3;else if(keys.s||keys.arrowdown)progress-=dt*4.5;else progress+=dt*5.15;progress=THREE.MathUtils.clamp(progress,0,110);jumpV-=dt*13;jumpY=Math.max(0,jumpY+jumpV*dt);if(jumpY===0)jumpV=0;player.position.x=THREE.MathUtils.damp(player.position.x,playerX,10,dt);player.position.y=.2+jumpY;player.position.z=-progress;avatar.rotation.z=THREE.MathUtils.damp(avatar.rotation.z,-move*.13,8,dt);avatar.position.y=Math.sin(elapsed*13)*.025;limbs[0].rotation.z=Math.sin(elapsed*9)*.12;limbs[1].rotation.x=Math.sin(elapsed*9)*.4;limbs[2].rotation.x=-Math.sin(elapsed*9)*.4;
  $('#distance').textContent=`${Math.max(0,Math.round(108-progress))} M`;
  for(const c of cores){if(c.taken)continue;c.g.rotation.y+=dt*1.6;c.g.position.y=1.15+Math.sin(elapsed*3+c.z)*.12;if(Math.abs(c.z+progress)<1.5&&Math.abs(playerX-c.x)<1.45){c.taken=true;c.g.visible=false;coresTaken++;pulseCharges=Math.min(3,pulseCharges+1);$('#pulse-count').innerHTML=`0${pulseCharges} <small>CHARGES</small>`;updateCores();setAlert(Math.max(0,alert-9));showToast('CIPHER CORE SECURED · +1 PULSE')}}
  for(const o of obstacles){if(o.hit)continue;if(Math.abs(o.z+progress)<1.05&&Math.abs(playerX-o.x)<1.17){if(o.type==='vent'&&jumpY>.45){o.hit=true;o.g.visible=false;showToast('CLEAN VAULT');continue}o.hit=true;setAlert(alert+30);progress=Math.max(0,progress-2.5);showToast(o.type==='beacon'?'SECURITY BEACON · ALERT RAISED':'ROOF HAZARD · WATCH YOUR STEP');if(alert>=100)finish(false)}}
  for(const g of gates){if(g.open)continue;if(Math.abs(g.z+progress)<.95&&Math.abs(playerX)<3.7){setAlert(alert+24);progress=Math.max(0,progress-3);showToast('MAG-LOCK BARRIER · PRESS E');if(alert>=100)finish(false)}}if(alert>0)setAlert(alert-dt*1.1);
  $('#hint').textContent=progress<40?'▸ PULSE THE MAG-LOCK TO BREAK THROUGH':progress<77?'▸ CORE INBOUND · WATCH YOUR STEP':'▸ ENGINE CAB AHEAD';if(progress>=106){if(coresTaken===3)finish(true);else{showToast('ENGINE LOCKED · SECURE ALL 3 CORES');progress=103;setAlert(alert+12)}}
 }
 camera.position.x=THREE.MathUtils.damp(camera.position.x,player.position.x*.34,6,dt);camera.position.y=5.9;camera.position.z=player.position.z+10.8;camera.lookAt(player.position.x*.15,1,player.position.z-8.6);cyanLight.position.set(-5,5,-18);goldLight.position.set(4,3,-47);for(const s of snowflakes){s.position.y-=dt*(.9+Math.abs(s.position.z%2));s.position.x+=Math.sin(elapsed+s.position.z)*dt*.12;if(s.position.y<0){s.position.y=15;s.position.z=rand(-100,15)}}for(const c of cores)if(!c.taken)c.g.rotation.y+=dt*.35;renderer.render(scene,camera)}animate();

