import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.fog=new THREE.FogExp2(0x102c38,.012);const camera=new THREE.PerspectiveCamera(51,innerWidth/innerHeight,.1,240);camera.position.set(0,5.9,10.8);camera.lookAt(0,1,-8.6);
scene.add(new THREE.HemisphereLight(0xbde9ed,0x10202b,2));const moon=new THREE.DirectionalLight(0xd9f4f4,3.2);moon.position.set(-5,12,8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);const cyanLight=new THREE.PointLight(0x4bdbe7,18,24);scene.add(cyanLight);const goldLight=new THREE.PointLight(0xffbb5c,22,18);scene.add(goldLight);
const mat=(color,roughness=.7,metalness=.05,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:ei});const mats={roof:mat(0x263e48,.55,.3),edge:mat(0x82989a,.4,.5),body:mat(0x183642,.45,.4),dark:mat(0x101f28,.65,.3),snow:mat(0xd1e4dc,.88),ice:mat(0x72d9e3,.25,.5,0x1ba8b5,.8),gold:mat(0xffcb70,.3,.3,0xf0922b,.9),red:mat(0xff665c,.3,.1,0xe52323,1.2),player:mat(0x253d48,.42,.3),coat:mat(0xd08b4c,.55,.1),visor:mat(0x73edf1,.22,.5,0x30b9c9,.8),rail:mat(0x92b5b4,.4,.65),rock:mat(0x203944,.95)};
function box(parent,x,y,z,sx,sy,sz,material,cast=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=true;parent.add(m);return m}function sphere(parent,x,y,z,r,material){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
const world=new THREE.Group();scene.add(world);for(let i=0;i<8;i++){const z=18-i*17;box(world,0,-.35,z,8,.6,17,mats.body);box(world,0,-.01,z,7.45,.18,16.3,mats.roof);for(const x of [-3.88,3.88]){box(world,x,-.32,z,.22,.48,16.8,mats.edge);box(world,x,-.65,z,.07,.11,15,mats.gold,false)}for(const x of [-2.7,2.7])box(world,x,.12,z,.13,.14,15.8,mats.edge);for(let z2=z-7;z2<z+8;z2+=5)box(world,0,.1,z2,.33,.15,.25,mats.edge)}
const rand=(a,b)=>a+Math.random()*(b-a);for(let i=0;i<70;i++){const side=Math.random()<.5?-1:1,z=rand(-128,36),x=side*rand(6,24),h=rand(2,12),rot=rand(0,6);const mountain=new THREE.Mesh(new THREE.ConeGeometry(rand(2,8),h,5),mats.rock);mountain.position.set(x,h/2-2,z);mountain.rotation.y=rot;scene.add(mountain);const cap=new THREE.Mesh(new THREE.ConeGeometry(rand(1.4,5),h*.33,5),mats.snow);cap.position.set(x,h*.75-2,z);cap.rotation.y=rot;scene.add(cap)}for(const side of [-1,1])for(const x of [side*4.4,side*5.2])box(world,x,-.72,-43,.08,.08,125,mats.rail,false);
for(let i=0;i<90;i++){const s=sphere(scene,rand(-45,45),rand(7,28),rand(-130,20),rand(.025,.075),mats.ice);s.material=new THREE.MeshBasicMaterial({color:i%8===0?0x9ce8ef:0xc9f0e9})}const auroraMat=new THREE.MeshBasicMaterial({color:0x42c8b3,transparent:true,opacity:.08,side:THREE.DoubleSide,depthWrite:false});for(let i=0;i<5;i++){const ribbon=new THREE.Mesh(new THREE.PlaneGeometry(45,10,20,1),auroraMat);ribbon.position.set(-10+i*7,16,-55-i*8);ribbon.rotation.y=.18+i*.06;ribbon.rotation.z=.12;scene.add(ribbon)}
